class ComputeMorseSmaleSegmentation(Node):
    def __init__(self, parent_node_id : str):
        super().__init__(parent_node_id, types.Scalar, types.MorseSmaleSegmentation, locals())

    @classmethod
    def guardrails(cls):
        return [simplification_guardrail, piecewise_linear_guardrail]

    @classmethod
    def chat_description(cls):
        return "queued computing morse smale segmentation"

    @classmethod
    def description(cls):
        return 'Compute the piecewise-linear Morse-Smale segmentation of a scalar field.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar that represents the scalar field '
                           'whose piecewise-linear Morse-Smale segmentation we are computing.'}

