import os

from .nodeData import NodeData
from paraview.simple import *

class MorseSmaleSegmentation(NodeData):
    def __init__(self, msc):
        self.msc = msc

    def __getstate__(self):
        state = self.__dict__.copy()
        state["msc"] = None
        return state

    def save(self, dirname):
        super().save(dirname)
        SaveData(f"{dirname}/msc.vti", self.msc)

    @classmethod
    def load(cls, dirname):
        base = super().load(dirname)
        msc = XMLImageDataReader(FileName=[f"{dirname}/msc.vti"])
        msc.PointArrayStatus = ["Scalars__MorseSmaleManifold"]
        msc.TimeArray = 'None'
        base.msc = msc
        return base

    @classmethod
    def get_mcp_name(cls):
        return "ms_complex"

    def export(self, filename : str, partition_array_name : str):
        if filename[-4:] != ".vti":
            raise Exception("The only available export file type is VTK image data (.vti)")

        os.makedirs(os.path.dirname(os.path.abspath(filename)), exist_ok=True)

        renameArrays = RenameArrays(Input=self.msc)
        renameArrays.PointArrays = ["Scalars__MorseSmaleManifold", partition_array_name]

        SaveData(filename, renameArrays)
        Delete(renameArrays)

    @classmethod
    def get_export_description(cls):
        return "Saves the Morse-Smale segmentation of a scalar field associated with a node of type ms_complex."

    @classmethod
    def get_export_param_descriptions(cls):
        return {
            "filename": "The name of the file of the saved data. The extension determines the file type. currently, the only "
                        "supported file type is VTK image data (.vti).",
            "partition_array_name": "The name of the array that will be used to save the region identifiers in the MS segmentation."
        }

    @classmethod
    def chat_description(cls):
        return "Morse-Smale segmentation"

class MorseSmaleSegmentationEmbedding(NodeData):

    def __init__(self, msc, lut, dimensions):
        self.msc = msc
        self.lut = lut
        self.dimensions = dimensions

    def __getstate__(self):
        state = self.__dict__.copy()
        state["msc"] = None
        return state    

    def visualize(self, renderView):
        display = Show(self.msc, renderView, 'UniformGridRepresentation')

        outline = Outline(Input=self.msc)
        tube = Tube(Input=outline)
        tube.Radius = max(self.dimensions) * 0.0025
        Show(tube, renderView, 'GeometryRepresentation')

        LUT = GetColorTransferFunction('Scalars__MorseSmaleManifold')
        LUT.RGBPoints = self.lut
        LUT.ScalarRangeInitialized = 1.0

        display.Representation = 'Slice'
        display.ColorArrayName = ['POINTS', 'Scalars__MorseSmaleManifold']
        display.LookupTable = LUT

    @classmethod
    def get_mcp_name(cls):
        return "ms_complex_embedding"

    @classmethod
    def chat_description(cls):
        return "Morse-Smale segmentation embedding"
